// ---------------------------------------------------------------
// PUT YOUR SHARED SECRET HERE. It must match "webhook_secret" in
// ~/.clientmail/config.json. Anyone who learns your webhook URL can
// send mail from your account without it.
const SECRET = 'REPLACE_WITH_YOUR_SECRET';
// ---------------------------------------------------------------

const item = $input.first().json;
const body = item.body ?? item;

if (SECRET && SECRET !== 'REPLACE_WITH_YOUR_SECRET' && body.secret !== SECRET) {
  throw new Error('Unauthorized: webhook secret does not match');
}

// Connectivity probe from `clientmail check --ping` -- answer without sending.
if (body.probe === true) {
  return [{ json: { probe: true, ok: true } }];
}

for (const field of ['from', 'to', 'subject', 'html']) {
  if (!body[field]) {
    throw new Error('Missing required field: ' + field);
  }
}

// Turn the base64 attachments from the payload into n8n binary data. The Send
// Email node reads them by name from attachmentFields; an empty string there is
// safe, so one node handles mail with and without attachments.
const binary = {};
const names = [];
const atts = Array.isArray(body.attachments) ? body.attachments : [];
atts.forEach((a, i) => {
  const key = 'attachment_' + i;
  binary[key] = {
    data: a.data,
    mimeType: a.mimeType || 'application/octet-stream',
    fileName: a.fileName || key,
  };
  names.push(key);
});

return [{
  json: {
    probe: false,
    attachmentFields: names.join(','),
    attachmentCount: names.length,
    from: String(body.from),
    to: String(body.to),
    cc: String(body.cc || ''),
    bcc: String(body.bcc || ''),
    subject: String(body.subject),
    html: String(body.html),
    text: String(body.text || ''),
    replyTo: String(body.replyTo || ''),
    draftHash: String(body.draftHash || ''),
  },
  binary,
}];
